import ghidra.app.script.GhidraScript;import ghidra.program.model.symbol.*;import ghidra.program.model.listing.*;import ghidra.program.model.address.*;import java.io.*;
public class PacketSymbols extends GhidraScript {public void run() throws Exception{PrintWriter w=new PrintWriter(getScriptArgs()[0]);SymbolIterator si=currentProgram.getSymbolTable().getAllSymbols(true);while(si.hasNext()){Symbol s=si.next();String name=s.getName(true);if(name.matches("(?i).*(MsgPort|Param|Symbol|UsbControl|Editor|Firebird|Parker).*")){w.println(s.getAddress()+" "+name);if(s.getName().equals("vftable")){for(int n=0;n<35;n++){Address a=s.getAddress().add(4*n);int ptr=currentProgram.getMemory().getInt(a);Address dest=toAddr(Integer.toUnsignedLong(ptr));Function f=getFunctionAt(dest);if(f==null)break;w.println(" VTABLE "+a+" "+dest+" "+f.getName());}}}}w.close();}}
